    SELECT fn_get_dynamic_seq('utb_app_product')

INSERT INTO utb_app_product (
    office_seq
    , app_seq
    , product_seq
    , product_id
    , nice_version
    , product_class
    , product_group_id
    , product_count
    , product_name_ko
    , product_name_en
    , create_user
    , create_at
    , del_yn
    , note
) VALUES (
    #{officeSeq}
    , #{appSeq}
    , #{productSeq}
    , #{productId}
    , #{niceVersion}
    , #{productClass}
    , #{productGroupId}
    , #{productCount}
    , #{productNameKo}
    , #{productNameEn}
    , #{createUser}
    , CURRENT_TIMESTAMP
    , #{delYn}
    , #{note}
)

mapper.select:
SELECT class_no, nice_version, category_gb, class_nm_ko, class_nm_en, class_desc_ko, class_desc_en, del_yn, create_user, create_at, update_user, update_at FROM "MP_IPMS_PA".utb_nice_class_mst WHERE del_yn = 'N'
AND category_gb = #{categoryGb}
AND nice_version = #{niceVersion}
ORDER BY class_no ASC

SELECT product_id, nice_version, class_no, similarity_code, product_nm_ko, product_nm_en, note, del_yn, create_user, create_at, update_user, update_at FROM "MP_IPMS_PA".utb_product_mst WHERE del_yn = 'N'
AND nice_version = #{niceVersion}
AND class_no = #{classNo}
ORDER BY class_no ASC, similarity_code ASC, product_nm_ko ASC

SELECT
    COUNT(*)
FROM utb_app_product
WHERE product_group_id = #{productGroupId}
  AND app_seq = #{appSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'

